        raise TypeError("protocol_version must be passed in a tuple")

    version_handlers = { (3, 5): Bolt35Handler }

    if protocol_version:
        if protocol_version in version_handlers:
            return { protocol_version: version_handlers[protocol_version] }
        else:
            return {}
    else:
        return version_handlers

