import subprocess
from pathlib import Path

def xargs(cmd: tuple[str, ...], varargs: Sequence[str], *, color: bool = False, target_concurrency: int = 1, _max_length: int = _get_platform_max_length(), **kwargs: Any) -> tuple[int, bytes]:
    if color and _supports_pty():
        master_fd, slave_fd = os.openpty()
        kwargs["stdout"] = kwargs["stderr"] = slave_fd
    else:
        master_fd, slave_fd = None, None

    args = _prep_argument_list(cmd, varargs, _max_length)
    inputs = _get_input(args, master_fd, target_concurrency)

    if kwargs:
        process = subprocess.Popen(args, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, **kwargs)
    else:
        process = subprocess.Popen(args, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    stdout, stderr = process.communicate(input=inputs)

    if master_fd:
        os.close(master_fd)
        os.close(slave_fd)

    return_code = process.returncode
    if return_code:
        stderr = stderr.decode()

    return return_code, stdout

def _get_input(args: Sequence[str], master_fd: int | None, target_concurrency: int) -> bytes:
    if master_fd:
        with os.fdopen(master_fd, mode="wb") as stdin:
            stdin.write(bytes(args))
            for i in range(1, target_concurrency):
                with open(Path(args[0]).with_suffix(".{}.py".format(i)), "rb") as f:
                    stdin.write(f.read())

    return None

def _prep_argument_list(cmd: tuple[str, ...], varargs: Sequence[str], max_length: int) -> Sequence[str]:
    args = list(cmd)
    args.extend(varargs)
    for i, arg in enumerate(args):
        if len(arg) > max_length:
            args[i] = arg[:max_length]
    return args

