    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    The `cache` parameter should be a dict-like object
    The `key` parameter should be a callable that generates a key for the cache
    The `lock` parameter should be a lock object for the cache, or None
    """
    def wrapper(f):
        @wraps(f)
        def inner(*args, **kwargs):
            k = key(*args, **kwargs)
            with lock:
                if k in cache:
                    return cache[k]
                else:
                    result = f(*args, **kwargs)
                    cache[k] = result
                    return result
        return inner
    return wrapper

