def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    cache = dict()
    times = dict()

    def decorator(func):
        nonlocal maxsize, ttl, timer, typed

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = tuple(sorted(kwargs.items())) if typed else tuple(args)
            try:
                value, lookupTime = cache[key]
                if time.monotonic() - lookupTime <= ttl:
                    return value
            except (KeyError, TypeError):
                pass

            startTime = timer()
            value = func(*args, **kwargs)
            endTime = timer()
            cache[key] = (value, endTime)
            times[key] = (endTime - startTime).total_seconds() / 1000

            if len(cache) > maxsize:
                for key, (value, lookupTime) in cache.items():
                    if time.monotonic() - lookupTime > ttl:
                        del cache[key]
                        del times[key]
                        break

        return wrapper

