import collections
import time
import functools

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.

    Parameters
    ----------
    maxsize : int
        The maximum number of results to be stored in the cache.
    ttl : float
        The time-to-live value for each cache key in seconds.
    timer : callable
        The method used to track the clock.
    typed : bool
        If ``True``, the dictionary will be typed. Usually this is
        desirable for performance.
    """
    def decorating_function(user_function):
        cache = TTLCache(maxsize, ttl, timer, typed)
        return functools.update_wrapper(cache, user_function)

    return decorating_function

# The following is the Cache implementation used by ttl_cache
class TTLCache(collections.OrderedDict):
    """LRU Cache implementation with time-to-live (TTL) support.

    Arguments
    ----------
    maxsize : int
        The maximum number of items the cache can hold.
    ttl : float
        The time-to-live value in seconds.
    timer : callable
        A method that returns the current clock.
    typed : bool
        If ``True``, the dictionary will be typed. Usually this is
        desirable for performance.
    """

    def __init__(self, maxsize, ttl, timer, typed, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._ttl = ttl
        self._timer = timer
        self._maxsize = maxsize
        self._typed = typed

    def __getitem__(self, key):
        value = super().__getitem__(key)
        self.move_to_end(key)
        return value

    def __setitem__(self, key, value):
        if key in self:
            self.move_to_end(key)
        super().__setitem__(key, value)
        while len(self) > self._maxsize:
            self.popitem(last=False)

    def __contains__(self, key):
        if not super().__contains__(key):
            return False
        value = super().__getitem__(key)
        self.move_to_end(key)
        return True

    def get(self, key, default=None):
        try:
            return self[key]
        except KeyError:
            return default

    def setdefault(self, key, default=None):
        if key in self:
            value = self.get(key)
        else:
            self[key] = default
            value = self.get(key)
        return value

    def __len__(self):
        return len(self.items())

    def keys(self):
        # Return the keys, LRU to MRU
        return list(reversed(super().keys()))

    def add(self, key, value):
        if key not in self:
            super().__setitem__(key, value)
        else:
            self.move_to_end(key)
        while len(self) > self._maxsize:
            self.popitem(last=False)

    def extend(self, other):
        for key, value in other.items():
            self.add(key, value)

    def items(self):
        for key in self.keys():
            yield key, self[key]

    def values(self):
        for key in self.keys():
            yield self[key]

    def popitem(self, *args):
        pair = super().popitem(*args)
        if self._typed:
            return pair[0], pair[1]
        else:
            return pair

    def __delitem__(self, key):
        super().__delitem__(key)
        if self._typed:
            return

    def __repr__(self):
        return f"TTLCache({self.maxsize}, {self.ttl}, {self.timer}, {self.typed})"

