def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """

    class MRUCacher:
        def __init__(self, func, maxsize, typed):
            self.func = func
            self.cache = {}
            self.maxsize = maxsize
            self.typed = typed

        def __call__(self, *args):
            key = self._get_cache_key(args)
            if key in self.cache:
                value = self.cache[key]
                self._update_mru(key)
                return value
            else:
                value = self.func(*args)
                self._set_cache(key, value)
                return value

        def _get_cache_key(self, args):
            # return a tuple key for the cache
            if self.typed:
                return tuple((type(arg), arg) for arg in args)
            else:
                return tuple(args)

        def _update_mru(self, key):
            # update the MRU list
            value = self.cache.pop(key)
            self.cache[key] = value

        def _set_cache(self, key, value):
            # set the cache and check size
            self.cache[key] = value
            if len(self.cache) > self.maxsize:
                self.cache.popitem(last=False)

        def reset(self):
            # reset the cache
            self.cache.clear()

    return MRUCacher(maxsize=maxsize, typed=typed)

