def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    Parameters:
        cache (dict): The cache to store the results
        key (function): The key to use to store the result, by default, the key is the hash of the args
        lock (threading.Lock): The lock to use to prevent race conditions when storing the result
    """

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = key(*args, **kwargs)
            if lock:
                lock.acquire()
            try:
                result = cache.get(key)
                if result is None:
                    result = func(*args, **kwargs)
                    cache[key] = result
            finally:
                if lock:
                    lock.release()
            return result
        return wrapper
    return decorator

