def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Create a dictionary to store the number of classes in each hierarchy
    hierarchy = {}
    for cls in classes:
        hierarchy[cls] = 0

    # Iterate through the list of classes and count the number of times each one appears in the hierarchy
    for cls in classes:
        hierarchy[cls] += len(classes)

    # Find the hierarchy with the minimum number of classes
    min_hierarchy = None
    min_count = float("inf")
    for cls in hierarchy:
        if hierarchy[cls] < min_count:
            min_count = hierarchy[cls]
            min_hierarchy = [cls]
        elif hierarchy[cls] == min_count:
            min_hierarchy.append(cls)

    # Return the ordered minimum hierarchy
    return min_hierarchy

