class Declaration(object):
    def __init__(self, implemented):
        super().__init__()
        self.implemented = implemented
        self.body = None

    def __str__(self):
        lines = ['class ' + self.body.__name__ + ':']
        for i in self.implemented:
            lines.append('    implements ' + i.__name__)
        lines.append('')
        for i in self.body.__text_fields__:
            lines.append('    ' + i + ' = ...')
        lines.append('')
        for i in self.body.__data_fields__:
            lines.append('    ' + i + ' = { ... }')
        return '\n'.join(lines)


