    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """

    # Check if the input dicts are the same. If so, return an empty dict.
    if d1 is d2:
        return {}

    # If the input dicts are not the same, create an empty dictionary
    diff = {}

    # Iterate through the keys of d1 and compare them to the keys of d2
    for key in d1.keys():
        # If the key is not in d2, add it to the output dictionary
        if key not in d2.keys():
            diff[key] = d1[key]
        else:
            # If the key is in both d1 and d2, compare the values
            if d1[key] != d2[key]:
                # If the values are not the same, add the key and value from d1 to the output dictionary
                diff[key] = d1[key]
            # If the values are the same, do not add the key and value from d1 to the output dictionary

    # If the level of recursion is greater than 0, call difference recursively on the values of d1
    if level > 0:
        for key in d1.keys():
            # If the key is not in d2, treat the value as a dictionary. If it is not a dictionary, do not call difference on it.
            if key not in d2.keys():
                if isinstance(d1[key], dict):
                    diff[key] = difference(d1[key], {}, level-1)
            # If the key is in both d1 and d2, treat the value as a dictionary. If it is not a dictionary, do not call difference on it.
            elif isinstance(d1[key], dict) and isinstance(d2[key], dict):
                diff[key] = difference(d1[key], d2[key], level-1)

    return diff

