def difference(d1, d2, level=-1):
    if level == 0 or not isinstance(d1, dict) or not isinstance(d2, dict):
        return d1

    result = {}
    for key, val in d1.items():
        if key not in d2 or difference(val, d2[key], level - 1):
            result[key] = val

    return result

