def fill(self, coord, weight=1):
    if coord < self.xmin or coord > self.xmax:
        return

    bin_idx = int(round((coord - self.xmin) / self.bin_width))
    if bin_idx >= len(self.histogram):
        return

    self.histogram[bin_idx] += weight

