def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generate default observer schema from manifest dictionary.

    Args:
        manifest_dict (dict): Partial Kubernetes resource
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource. Defaults to False.

    Returns:
        dict: Generated partial observer schema

    This function creates a new dictionary from `manifest_dict` and replaces all
    non-list and non-dict values by `None`. In case of `first_level` dictionary
    (i.e. complete `observer_schema` for a resource), the values of the
    identifying fields are copied from the manifest file.

    """
    observer_schema = {}
    for k, v in manifest_dict.items():
        if isinstance(v, dict):
            observer_schema[k] = generate_default_observer_schema_dict(v)
        elif isinstance(v, list):
            observer_schema[k] = generate_default_observer_schema_list(v)
        else:
            observer_schema[k] = None
    if first_level:
        observer_schema.update({
            "id": manifest_dict["metadata"]["name"],
            "version": manifest_dict["apiVersion"],
            "kind": manifest_dict["kind"]
        })
    return observer_schema

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this function is called recursively to update a partial ``last_applied_manifest`` from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in ``last_applied_manifest`` if they are not yet present.
    """
    for i in range(len(observer_schema)):
        schema_elt = observer_schema[i]
        if schema_elt['type'] != 'array':
            continue

        if schema_elt['items'] is None:
            continue

        sub_schema = schema_elt['items']
        if sub_schema['type'] == 'object':
            for j in range(len(response)):
                if last_applied_manifest[i][j] is None:
                    last_applied_manifest[i][j] = {}

                update_last_applied_manifest_dict_from_resp(last_applied_manifest[i][j], sub_schema['properties'], response[j])
        else:
            for j in range(len(response)):
                if last_applied_manifest[i][j] is None:
                    last_applied_manifest[i][j] = []

                update_last_applied_manifest_list_from_resp(last_applied_manifest[i][j], sub_schema, response[j])

