        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    ``last_applied_manifest`` if they are not yet present.
    """
    for observed_field in observer_schema:
        if isinstance(observed_field, dict):
            if len(observed_field) != 1:
                continue
            key, value = observed_field.popitem()
            if key not in last_applied_manifest:
                last_applied_manifest[key] = update_last_applied_manifest_dict_from_resp({}, value, response)
        elif isinstance(observed_field, list):
            if len(observed_field) != 1:
                continue
            key, value = observed_field[0]
            if key not in last_applied_manifest:
                last_applied_manifest[key] = update_last_applied_manifest_list_from_resp([], value, response)
        elif key not in last_applied_manifest:
            last_applied_manifest[key] = response[key]

