    """
    Together with ``update_last_applied_manifest_dict_from_resp``, this function is called recursively to update a partial ``last_applied_manifest`` from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in ``last_applied_manifest`` if they are not yet present.
    """
    for i in range(len(observer_schema)):
        if i >= len(response):
            response.append(None)
        if isinstance(observer_schema[i], dict):
            if isinstance(response[i], list):
                last_applied_manifest.append(update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema[i], response[i]))
            else:
                if response[i] is not None:
                    last_applied_manifest.append(response[i])
                else:
                    last_applied_manifest.append(None)
        else:
            if response[i] is None:
                last_applied_manifest.append(None)
            else:
                last_applied_manifest.append(response[i])

