def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]):
        """
        Convert the SQL query to use the out-style parameters instead of
        the in-style parameters.

        Parameters:
            sql (str or bytes): The SQL query
            params (Mapping or Sequence): The set of in-style parameters.

        Returns:
            tuple: A tuple containing:

            - The formatted SQL query (str or bytes)
            - The set of converted out-style parameters (dict or list)
        """

        if not self.in_style:
            return sql, params

        processed_params = {}

        # Convert in-style parameters to out-style parameters
        if isinstance(params, Mapping):
            processed_params = {f":{key}": value for key, value in params.items()}
        elif isinstance(params, Sequence):
            for i, value in enumerate(params):
                processed_params[f":{i}"] = value

        # Replace in-style parameters in SQL query
        sql = sql.replace(str(self.in_style.prefix), str(self.sql_style.prefix))
        sql = sql.replace(str(self.in_style.suffix), str(self.sql_style.suffix))

        for param in re.findall(r'[?]|[:\w]+', sql):
            if param in processed_params:
                if isinstance(processed_params[param], WILDCARD):
                    sql = sql.replace(param, self.sql_style.wildcard)
                elif isinstance(processed_params[param], ANY):
                    sql = sql.replace(param, self.sql_style.any)
                else:
                    sql = sql.replace(param, '?')
            else:
                raise ParameterError(f"Parameter not found: {param}")

        return sql, processed_params

