class SQLParams:
    def __init__(self, in_style, params):
        self.in_style = in_style
        self.params = params

    def format(sql, params):
        in_style = self.in_style
        if in_style == 'named':
            assert isinstance(params, collections.abc.Mapping)
            params = params.items()

        if in_style == 'ordinal':
            assert isinstance(params, collections.abc.Sequence)

        num_params = len(params)
        i = 0
        while i < num_params:
            sql = sql.replace(f'${i + 1}', f'@p{i + 1}', 1)
            i += 1

        return (sql, params)

