def formatmany(self, sql, many_params):
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """

    # Check if the SQL query is a unicode string
    if type(sql) is str:
        is_bytes = False
    else:
        is_bytes = True

    # Check if the many_params is an iterable
    if type(many_params) is list or type(many_params) is tuple:
        is_params_list = True
    else:
        is_params_list = False

    # Check if the many_params is an iterable of dictionaries
    if is_params_list and type(many_params[0]) is dict:
        is_params_dict = True
    else:
        is_params_dict = False

    # Check if the many_params is an iterable of tuples
    if is_params_list and type(many_params[0]) is tuple:
        is_params_tuple = True
    else:
        is_params_tuple = False

    # Check if the many_params is an iterable of sequences
    if is_params_list and type(many_params[0]) is not dict and type(many_params[0]) is not tuple:
        is_params_seq = True
    else:
        is_params_seq = False

    # Check if the SQLParams.in_style is a named parameter style
    if self.in_style is "named":
        use_named_params = True
    else:
        use_named_params = False

    # Check if the SQLParams.in_style is an ordinal parameter style
    if self.in_style is "ordinal":
        use_ordinal_params = True
    else:
        use_ordinal_params = False

    # Check if the input parameters are valid
    if not is_params_dict and not is_params_tuple and not is_params_seq:
        raise ValueError("Many parameters must be a list or tuple of dictionaries or tuples.")
    if is_params_dict and not use_named_params:
        raise ValueError("Many parameters must be a list or tuple of tuples when using ordinal parameters style.")
    if is_params_tuple and not use_ordinal_params:
        raise ValueError("Many parameters must be a list or tuple of dictionaries when using named parameters style.")
    if is_params_seq and not use_ordinal_params and not use_named_params:
        raise ValueError("Many parameters must be a list or tuple of dictionaries or tuples when using ordinal parameters style.")

    # Format the SQL query
    if use_named_params:
        # Replace named parameters with unnamed parameters
        new_sql = sql.replace(":", "")
        new_sql = new_sql.replace("@", "")
        new_sql = new_sql.lstrip("$")
    else:
        # Replace ordinal parameters with unnamed parameters
