    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Check for a type field if the extract_spec_version parameter is not given
    if extract_spec_version:
        type_value = inventory.get('type')
        if type_value is not None:
            try:
                spec_version = SpecVersion(type_value)
            except ValueError:
                spec_version = self.spec_version
        else:
            spec_version = self.spec_version
    else:
        spec_version = self.spec_version

    # Validate the inventory against the specified specification version
    for field, validators in spec_version.get_validators().items():
        value = inventory.get(field)
        if value is not None:
            for validator in validators:
                if not validator.check(value):
                    return False

    # If the inventory is valid, return True
    return True

