def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # check if the fixity block is present
    if not fixity:
        return False

    # check if the fixity block is structured correctly
    if not isinstance(fixity, dict):
        return False

    # check if the fixity block has all the necessary attributes
    if not all(attribute in fixity for attribute in {'files', 'fixity'}):
        return False

    # check if the files in the fixity block are present in the manifest
    for file in fixity['files']:
        if file not in manifest_files:
            return False

    # check if the fixity property of the files is correctly formatted
    for file in fixity['files'].values():
        if not isinstance(file, dict) or not all(property in file for property in {'sha1', 'size'}):
            return False

    # check if the fixity is correctly formatted
    if not all(attribute in fixity['fixity'] for attribute in {'algorithm', 'value'}):
        return False

    # check if the algorithm is supported
    if fixity['algorithm'] not in ('SHA-1', 'SHA256'):
        return False

    # check if the fixity value is correctly formatted
    if not isinstance(fixity['value'], str):
        return False

    # check if the size is correctly formatted
    if not isinstance(fixity['size'], int):
        return False

    # check if the size matches the file size
    if len(fixity['value']) != fixity['size']:
        return False

    # check if the SHA1 or SHA256 hash matches the calculated hash
    if fixity['algorithm'] == 'SHA-1':
        calculated_hash = hashlib.sha1(manifest_files.get(fixity['files']).encode()).hexdigest()
    else:
        calculated_hash = hashlib.sha256(manifest_files.get(fixity['files']).encode()).hexdigest()
    if fixity['value'] != calculated_hash:
        return False

    # if no issues were found, return True
    return True

