def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for expr1, expr2 in zip(args, args[1:]):
        if is_absorption(expr1, expr2):
            new_args.append(expr1)
        elif is_negative_absorption(expr1, expr2):
            new_args.append(distribute_to_and(expr1, expr2))
        else:
            new_args.append(expr1)
            new_args.append(expr2)
    return new_args

def is_absorption(expr1, expr2):
    return (is_and(expr1) and is_or(expr2) and expr1[0][0] == expr2[1]
            or is_or(expr1) and is_and(expr2) and expr1[1] == expr2[0])

def is_negative_absorption(expr1, expr2):
    return (is_and(expr1) and is_or(expr2) and expr1[0][0] == ~expr2[1]
            or is_or(expr1) and is_and(expr2) and expr1[1] == ~expr2[0])

def distribute_to_and(expr1, expr2):
    return (expr1[0] & distribute_to_or(expr1[1], expr2[0]),
            expr2[1] & distribute_to_or(expr1[1], expr2[1]))

def distribute_to_or(expr1, expr2):
    return expr1 | expr2

