import subprocess
import shlex
import os

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Split the commands into a list of individual components
    commands = shlex.split(commands)

    # Run the command(s)
    if verbose:
        print("Running command(s): %s" % " ".join(commands))

    if env:
        env = os.environ.copy()
        env.update(env)

    try:
        output = subprocess.check_output(commands, stderr=subprocess.STDOUT if hide_stderr else None, cwd=cwd, env=env)
    except subprocess.CalledProcessError as e:
        if verbose:
            print("Command failed with exit code %d:" % e.returncode)
            print(e.output.decode("utf-8"))

        raise e

    if verbose:
        print("Output:")
        print(output.decode("utf-8"))

