def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = self.inventory
    version_inventories = []
    version_content_digests = {}

    for version_dir in version_dirs:
        version_inventories.append(self.inventories[version_dir])

        for content_digest in version_inventories[len(version_inventories) - 1]['contentDigests']:
            if self.digest in version_content_digests:
                version_content_digests[self.digest].append(content_digest)
            else:
                version_content_digests[content_digest] = []

    # Check that inventories exist for all versions
    for index, inventory in enumerate(version_inventories):
        if not inventory:
            raise ValidationError("Version {0} does not have an inventory".format(index + 1))

    # Check that version sequencing is correct
    for index, inventory in enumerate(version_inventories):
        if inventory['author'].lower() != self.author.lower():
            raise ValidationError("Version {0} author does not match the root document".format(index + 1))

    # Check that content digests are the same in each version
    for version in version_content_digests:
        for content_digest in version_content_digests[version]:
            if content_digest not in root_inventory['contentDigests']:
                raise ValidationError("Content digest {0} found in version {1} does not appear in the root inventory".format(content_digest, version))

        for root_content_digest in root_inventory['contentDigests']:
            if root_content_digest not in version_content_digests[version]:
                raise ValidationError("Content digest {0} found in the root inventory is missing from version {1}".format(root_content_digest, version))

