def parse_subparser_arguments(unparsed_arguments, subparsers):
    """Parses the specified arguments and distributes them among the given subparsers.

    Args:
        unparsed_arguments: A sequence of strings containing the arguments to be parsed.
        subparsers: A dictionary mapping the names of subparsers to their respective argparse.ArgumentParser instances.

    Returns:
        A tuple containing two elements:
            - A dictionary mapping the names of subparsers to the parsed namespace of their respective arguments.
            - A list containing the remaining arguments that were not claimed by any subparser.
    """
    # Create a new parser that includes all common arguments and combines their actions
    common_parser = ArgumentParser(add_help=False)
    for parser in subparsers.values():
        for action in parser._actions:
            if action.option_strings:
                if action.dest == "help":
                    continue  # We will handle this manually
                common_parser.add_argument(*action.option_strings, dest=action.dest, aliases=action.aliases, help=action.help)

    # Parse the common arguments
    common_namespace, remaining_args = common_parser.parse_known_args(unparsed_arguments)

    # Create a separate parser for each subparser and give it the necessary arguments
    parser_dict = {}
    for name, parser in subparsers.items():
        sub_parser = ArgumentParser(add_help=False)
        for action in parser._actions:
            if action.dest != "help":
                sub_parser.add_argument(action.option_strings, dest=action.dest, help=action.help)
        parser_dict[name] = sub_parser.parse_args(remaining_args, namespace=common_namespace)

    return parser_dict, remaining_args

