def format_frequency(frequency):
    '''
    Given a datetime.timedelta instance representing a duration in seconds, return a
    human-readable string representing the duration with a unit of time and an
    integer number of units.

    For example, 1 day and 1 hour returns "1 day 1 hour".

    Raise ValueError if the given frequency is not a datetime.timedelta instance.
    '''

    if not isinstance(frequency, datetime.timedelta):
        raise ValueError("frequency must be a datetime.timedelta instance")

    days = frequency.days
    hours = frequency.seconds // 3600
    minutes = frequency.seconds % 3600 // 60
    seconds = frequency.seconds % 60

    parts = []

    if days:
        parts.append("{} day{}".format(days, "s" if days != 1 else ""))

    if hours or days:
        parts.append("{} hour{}".format(hours, "s" if hours != 1 else ""))

    if minutes or hours or days:
        parts.append("{} minute{}".format(minutes, "s" if minutes != 1 else ""))

    if seconds != 0 or not parts:
        parts.append("{} second{}".format(seconds, "s" if seconds != 1 else ""))

    return " ".join(parts)

