def subprocess_run_helper(func, *args, timeout, extra_env=None):
    """Run a function in a sub-process."""
    import subprocess

    if extra_env is None:
        extra_env = {}

    def get_process():
        """Get the process."""
        return subprocess.run(
            [func.__module__ + "." + func.__name__] + list(args),
            env=dict(os.environ, **extra_env),
            check=True,
            timeout=timeout,
        )

    return get_process

