def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """Find the roots in some sort of transitive hierarchy.

    Args:
        graph (Graph): The graph to search
        prop (URIRef): The property that defines the hierarchy
        roots (Optional[Set[Node]]): A set of nodes to start with. Defaults to None.

    Returns:
        Set[Node]: A set of all roots of the transitive hierarchy
    """

    if not roots:
        roots = set()
        for s, o in graph.subject_objects(predicate=prop):
            roots.add(s)

    for root in frozenset(roots):
        for _, o in graph.subject_objects(subject=root, predicate=prop):
            if o not in roots:
                roots.add(o)
                find_roots(graph, prop, roots)

    return roots

