def load_configurations(config_filenames: Sequence[str], overrides=None, resolve_env=True) -> Tuple[Dict[str, Dict], Sequence[LogRecord]]:
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """

    configs = {}
    parse_errors = []

    for config_filename in config_filenames:
        try:
            with open(config_filename) as f:
                config = yaml.safe_load(f.read())
        except IOError as e:
            parse_errors.append(LogRecord(
                level=logging.ERROR,
                message=f"Error reading configuration file: {config_filename}: {e}",
                path=config_filename,
                line=0
            ))
        else:
            # Override values in the configuration file with those from an override text file.
            if overrides:
                for key, value in overrides.items():
                    config.setdefault(key, {}).update(value)

            # Resolve environment variables in the configuration.
            if resolve_env:
                config = resolve_env_vars(config)

            # Validate the configuration and add it to the result.
            configs[config_filename] = config
            parse_errors.extend(validate_config(config, config_filename))

    return configs, parse_errors


def resolve_env_vars(config: Mapping) -> Dict:
    """
    Recursively resolves environment variables in the given configuration mapping.
    """

    config_copy = deepcopy(config)
    for key, value in config.items():
        if isinstance(value, str) and value.startswith('$'):
            resolved_value = os.environ.get(value[1:])
            config_copy[key] = resolved_value if resolved_value is not None else value
        elif isinstance(value, MutableMapping):
            config_copy[key] = resolve_env_vars(value)

    return config_copy


def validate_config(config: Mapping, config_filename: str) -> Sequence[LogRecord]:
    """
    Validates the given configuration mapping. Returns a sequence of LogRecord instances,
    containing any parse errors encountered.
    """

    errors = []
    for key, value in config.items():
        if key == 'logging':
            if not isinstance(value, Sequence):
                errors.append(LogRecord(
                    level=logging.ERROR,
                    message=f"Logging section in configuration file {config_filename} is not a list.",
                    path=f'logging',
                    line=0
                ))
            else:
                for index, level in enumerate(value):
                    if not isinstance(level, str):
                        errors.append(LogRecord(
                            level=logging.ERROR,
                            message=f"Logging level {index} in configuration file {config_filename} is not a string.",
                            path=f'logging',
                            line=index
                        ))
                    elif level not in ('DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL'):
                        errors.append(LogRecord(
                            level=logging.ERROR,
                            message=f"Logging level {index} in configuration file {config_filename} is not a valid level.",
                            path=f'logging',
                            line=index
                        ))
        elif key.startswith('logging.'):
            errors.append(LogRecord(
                level=logging.ERROR,
                message=f"Invalid logging configuration key: {key}",
                path=f'logging',
                line=0
            ))

    return errors

