def load_configurations(config_filenames, overrides=None, resolve_env=True):
    # Set up logging
    logger = logging.getLogger('globus_sdk.conf')
    handler = logging.StreamHandler()
    formatter = logging.Formatter('%(asctime)s [%(name)s] %(message)s')
    handler.setFormatter(formatter)
    logger.addHandler(handler)

    # Load and validate all configurations
    all_configs = OrderedDict()
    errors = []
    for filename in config_filenames:
        # Expand environment variables in configuration paths
        if resolve_env:
            filename = os.path.expandvars(filename)

        logger.debug('Loading configuration from %s', filename)

        try:
            with open(filename, 'rb') as f:
                config = f.read()

            # Allow inheritance of top-level configuration from another
            # config file
            if overrides:
                for override in overrides:
                    if override.endswith('.conf'):
                        raise ValueError('`overrides` must be a dictionary')
                    elif override.startswith('import:'):
                        raise ValueError('Import statements are not allowed in `overrides`')
                    else:
                        config += '\n' + override + '\n'
            try:
                config_dict = {
                    'sdk': validated_config(config),
                }
            except Exception as e:
                errors.extend(logging.makeLogRecord(('ERROR', 'globus_sdk.conf', logging.ERROR, repr(e), (), None)))
                config_dict = OrderedDict()

        except IOError as e:
            errors.extend(logging.makeLogRecord(('ERROR', 'globus_sdk.conf', logging.ERROR, repr(e), (), None)))
            config_dict = OrderedDict()

        all_configs[filename] = config_dict

    return all_configs, errors

