def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Check if a protocol version is passed in
    if protocol_version:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed in as a tuple")
    else:
        protocol_version = None

    # Create a dictionary to hold the supported handlers
    supported_handlers = {}

    # If a specific protocol version is passed in, we can handle it directly
    if protocol_version:
        # Check if the protocol version is supported
        if protocol_version not in cls.SUPPORTED_PROTOCOLS:
            # If it's not supported, return an empty dictionary
            return {}
        else:
            # Return a dictionary containing the handler class for the requested version
            return {protocol_version: cls.SUPPORTED_PROTOCOLS[protocol_version]}

    # If no protocol version is passed in, we need to check all available protocol versions
    else:
        # Iterate over all supported protocol versions
        for version, handler_class in cls.SUPPORTED_PROTOCOLS.items():
            # If the handler class is supported, add it to the dictionary
            if handler_class:
                supported_handlers[version] = handler_class
        return supported_handlers

