def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.

    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Check for input errors
    if bufsize is not None:
        if not isinstance(bufsize, int):
            raise ValueError("bufsize must be an integer")
        if bufsize < 1:
            raise ValueError("bufsize must be >= 1")

    # Handle buffered sequence types
    if hasattr(seq, "buffer"):
        buf = seq.buffer
        if bufsize is None:
            bufsize = len(buf)
        else:
            bufsize = min(len(buf), bufsize)
        seq = buf[:bufsize]

    # Handle non-sequence types
    if not isinstance(seq, abc.Sequence):
        seq = (seq,)

    return seq, type(seq)

