import inspect

def verify_class(iface, candidate, tentative=False):
    """
    Verify that the `candidate` class might correctly provide `iface`.
    """
    if not isinstance(candidate, type):
        raise TypeError("The candidate is not a class.")
    if not isinstance(iface, type):
        raise TypeError("The interface is not a class.")
    if tentative:
        if not hasattr(candidate, "tentative_iface"):
            return False
        candidate_iface = getattr(candidate, "tentative_iface")
    else:
        candidate_iface = candidate if issubclass(candidate, iface) else getattr(candidate, "iface", None)
