        return False, "Candidate must be an instance of interface class"

    # Check if the candidate has all the required attributes
    for attr in iface.REQUIRED_ATTRIBS:
        if attr not in candidate.__dict__:
            return False, f"Candidate missing required attribute: {attr}"

    # Check if the candidate meets the required methods
    for method in iface.REQUIRED_METHODS:
        if not hasattr(candidate, method):
            return False, f"Candidate missing required method: {method}"

    # Check if the candidate has any additional methods
    if iface.OPTIONAL_METHODS:
        for method in iface.OPTIONAL_METHODS:
            if method not in candidate:
                continue
            else:
                # Check if the method signature matches that of the interface
                try:
                    sig = inspect.signature(candidate)
                except ValueError:
                    # Struct functions do not have a proper signature
                    continue
                else:
                    if iface.OPTIONAL_METHODS[method] != sig:
                        return False, f"Candidate has incorrect method signature for optional method: {method}"

    # If tentative is True, it means that the candidate has already been verified
    # and the extra checks should not be performed
    if not tentative:
        # Check if the candidate has any additional attributes
        if iface.OPTIONAL_ATTRIBS:
            for attr in iface.OPTIONAL_ATTRIBS:
                if attr not in candidate.__dict__:
