                    # Check if the attribute type matches that of the interface
                    attr_type = type(getattr(candidate, attr))
                    if attr_type not in iface.OPTIONAL_ATTRIBS[attr]:
                        return False, f"Candidate has incorrect type for optional attribute: {attr}"

        # Check if the candidate meets the required properties
        if iface.REQUIRED_PROPS:
            for prop in iface.REQUIRED_PROPS:
                if not candidate.propGetter(prop):
                    return False, f"Candidate must return true for required property: {prop}"

        # Check if the candidate has any additional properties
