def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # get base metaclasses
    metaclasses = [type(b) for b in bases if hasattr(b, "__metaclass__")]
    if not metaclasses:
        return None
    # find the most derived metaclass
    if explicit_mc:
        for mc in metaclasses:
            if isinstance(explicit_mc, mc):
                return explicit_mc
    return max(metaclasses, key=metaclasses.index)

