def fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if self.zone and self.zone != dt.tzinfo:
        if self.zone == utc:
            return dt.replace(tzinfo=utc)
        elif dt.tzinfo == utc:
            return self.zone.fromutc(dt)
        else:
            raise ValueError("Cannot convert naive datetime to {0}".format(self))
    return dt

