        if start < end:
            if code_block_re.search(text[start:end]):
                replaced_text += text[start:end]
                start = end
            else:
                if replacer is not None:
                    replaced_text += text[start:end].replace('<', '&lt;').replace('>', '&gt;')
                else:
                    replaced_text += text[start:end]
                start = end
    return tags, replaced_text

