    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """

    import requests

    # Set default document path
    if not document_path:
        document_path = url + "/.well-known/nodeinfo"

    # Make API request for NodeInfo data
    response = requests.get(document_path)

    # Check for HTTP errors
    if response.status_code != 200:
        raise ValueError("Failed to get NodeInfo data from " + document_path + ". Status code: " + str(response.status_code))

    # Parse NodeInfo data as JSON
    nodeinfo_data = response.json()

    # Check for required keys
    required_keys = ["software", "protocols", "services"]
    for key in required_keys:
        if key not in nodeinfo_data:
            raise ValueError("NodeInfo data missing required key: " + key)

    # Check types of keys
    software_type = type(nodeinfo_data["software"])
    if software_type is not dict:
        raise ValueError("NodeInfo key 'software' is not a dictionary")

