class DiasporaWebfingerLexer:
    def __init__(self):
        self.states = {
            "INITIAL": {
                "}": "END",
                "\"": "DOUBLE_QUOTE",
                "{": "START_JSON",
                "\\": "BACKSLASH"
            },
            "DOUBLE_QUOTE": {
                "\\": "BACKSLASH",
                "\"": "END_DOUBLE_QUOTE"
            },
            "START_JSON": {
                "}": "END_JSON",
                "]": "END_JSON_ARRAY",
                "{": "START_JSON",
                "\"": "DOUBLE_QUOTE"
            },
            "BACKSLASH": {
                "\"": "DOUBLE_QUOTE_ESCAPE",
                "\\": "BACKSLASH_ESCAPE"
            },
            "BACKSLASH_ESCAPE": {
                "\"": "DOUBLE_QUOTE",
                "\\": "BACKSLASH"
            },
            "DOUBLE_QUOTE_ESCAPE": {
                "\"": "DOUBLE_QUOTE"
            },
            "END_DOUBLE_QUOTE": {
                "}": "END",
                "\\": "BACKSLASH"
            },
            "END_JSON": {
                "}": "END"
            },
            "END_JSON_ARRAY": {
                "]": "END"
            }
        }

    def get_state(self, character):
        return self.states[self.current_state][character]

    def get_token(self, character):
        token = self.current_character
        if token in ["\"", "\\", "}"]:
            self.current_state = self.get_state(token)
        elif token == "{":
            self.current_state = "START_JSON"
        if token == "\\":
            self.current_state = "BACKSLASH"
        if self.current_state == "DOUBLE_QUOTE_ESCAPE":
            token = "\\"
        elif self.current_state == "BACKSLASH_ESCAPE":
            token = "\\"
        return token

# Define the Diaspora webfinger parser
class DiasporaWebfingerParser:
    def __init__(self, lexer):
        self.lexer = lexer
        self.tokens = []
        self.current_token = None

    def parse(self, document):
        for character in document:
            token = self.get_token(character)
            if token:
                self.tokens.append(token)
        return self.parse_response()

    def parse_response(self):
        response = {}
        while True:
            token = self.get_next_token()
            if not token:
                break
            if token == "}":
                break
            key = self.parse_key()
            value = self.parse_value()
            response[key] = value
        return response

    def parse_key(self):
        token = self.get_next_token()
        if token != "\"":
            raise ValueError("Expected key to be double-quoted")
        return self.parse_string()

    def parse_value(self):
        token = self.get_next_token()
        if token == "{":
            return self.parse_object()
        elif token == "[":
            return self.parse_array()
        elif token == "\"":
            return self.parse_string()
        elif token in ["true", "false"]:
            return self.parse_bool()
        elif token[0] == "-":
            return self.parse_number()
        else:
            raise ValueError("Unexpected token: %s" % token)

    def parse_object(self):
        object = {}
        while True:
            token = self.get_next_token()
            if token != "\"":
                raise ValueError("Expected key to be double-quoted")
            key = self.parse_string()
            token = self.get_next_token()
            if token != ":":
                raise ValueError("Expected ':' after key")
            value = self.parse_value()
            object[key] = value
            token = self.get_next_token()
            if token == "}":
                break
        return object

    def parse_array(self):
        array = []
        while True:
            value = self.parse_value()
            array.append(value)
            token = self.get_next_token()
            if token == "]":
                break
        return array

    def get_next_token(self):
        while True:
            token = self.current_token
            if self.current_token is None:
                token = self.get_token(self.lexer.get_character())
            if token:
                self.current_token = token
                return token

    def get_token(self, character):
        for state in self.lexer.states.get(self.lexer.current_state, []):
            token = state.get(character)
            if token:
                self.lexer.current_state = token
                return token
