def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    spec = self.spec
    default_args = {}

    for arg_name, arg_spec in spec.parameters.items():
        if arg_spec["annotation"] != Ellipsis:
            default_val = arg_spec["default"]
            if default_val is not arg_spec["default"]:
                default_args[arg_name] = default_val
            else:
                default_val = None
        if default_val is None:
            possible_defaults = []
            if hasattr(spec, "defaults"):
                possible_defaults.extend(spec.defaults)
            if hasattr(spec, "kwonlydefaults"):
                possible_defaults.extend(spec.kwonlydefaults)
            try:
                default_n = possible_defaults.index(arg_name)
                default_val = possible_defaults[default_n + 1]
                if default_val is not arg_spec["default"]:
                    default_args[arg_name] = default_val
            except ValueError:
                pass

    if spec.varargs is not None:
        varargs = spec.varargs
    else:
        varargs = list(spec.annotations.keys())[1:]

    for vararg in varargs[1:]:
        default_val = spec.annotations.get(vararg)
        if default_val is not None:
            default_args[vararg] = default_val

    for arg_name, arg_val in self.kwargs.items():
        if arg_val is not None and arg_val is not utils.MISSING:
            default_args[arg_name] = arg_val

    return default_args

