        """Resolve arguments' values from spec and other sources.

        The values in the spec override the defaults from the other sources.
        """
        spec = self.get_spec()

        kwargs = {}
        for param in spec.parameters:
            spec_default = param.default
            # Note that the default value from the spec is required and should be used.
            if isinstance(spec_default, str) and spec_default.startswith('!!'):
                spec_default = spec_default[2:]
            else:
                spec_default = None

            # Fulfill non-placeholder arguments:
            if not is_placeholder:
                # If the default value is an environment variable, use it to resolve.
                if isinstance(default_value, str) and default_value.startswith('$')):
                    default_value = os.getenv(default_value[1:], default_value)
                kwargs[param.name] = default_value
                continue

            # Check the other sources:
            if 'kwargs' in self.__dict__:
                default_value = self.kwargs.get(param.name)
                if default_value is not None:
                    kwargs[param.name] = default_value
                    continue
            if '_' + param.name in self.__dict__:
